    62→
    63→type NetworkModules = {
    64→  opts: NetworkOptions;
    65→  privateKey: PrivateKey;
    66→  config: BeaconConfig;
    67→  logger: LoggerNode;
    68→  chain: IBeaconChain;
    69→  networkEventBus: NetworkEventBus;
    70→  aggregatorTracker: AggregatorTracker;
    71→  networkProcessor: NetworkProcessor;
    72→  core: INetworkCore;
    73→};
    74→
    75→export type NetworkInitModules = {
    76→  opts: NetworkOptions;
    77→  config: BeaconConfig;
    78→  privateKey: PrivateKey;
    79→  peerStoreDir?: string;
    80→  logger: LoggerNode;
    81→  metrics: Metrics | null;
    82→  chain: IBeaconChain;
    83→  db: IBeaconDb;
    84→  getReqRespHandler: GetReqRespHandlerFn;
    85→  // Optionally pass custom GossipHandlers, for testing
    86→  gossipHandlers?: GossipHandlers;
    87→};
    88→
    89→/**
    90→ * Must support running both on worker and on main thread.
    91→ *
    92→ * Exists a front class that's what consumers interact with.
    93→ * This class will multiplex between:
    94→ * - libp2p in worker
    95→ * - libp2p in main thread
    96→ */
    97→export class Network implements INetwork {
    98→  readonly peerId: PeerId;
    99→  readonly custodyConfig: CustodyConfig;
   100→  // TODO: Make private
   101→  readonly events: INetworkEventBus;
   102→
   103→  private readonly logger: LoggerNode;
   104→  private readonly config: BeaconConfig;
   105→  private readonly clock: IClock;
   106→  private readonly chain: IBeaconChain;
   107→  // Used only for sleep() statements
   108→  private readonly controller: AbortController;
   109→
   110→  // TODO: Review
   111→  private readonly networkProcessor: NetworkProcessor;
   112→  private readonly core: INetworkCore;
   113→  private readonly aggregatorTracker: AggregatorTracker;
   114→
   115→  private subscribedToCoreTopics = false;
   116→  private connectedPeersSyncMeta = new Map<PeerIdStr, Omit<PeerSyncMeta, "peerId">>();
   117→
   118→  constructor(modules: NetworkModules) {
   119→    this.peerId = peerIdFromPrivateKey(modules.privateKey);
   120→    this.config = modules.config;
   121→    this.custodyConfig = modules.chain.custodyConfig;
   122→    this.logger = modules.logger;
   123→    this.chain = modules.chain;
   124→    this.clock = modules.chain.clock;
   125→    this.controller = new AbortController();
   126→    this.events = modules.networkEventBus;
   127→    this.networkProcessor = modules.networkProcessor;
   128→    this.core = modules.core;
   129→    this.aggregatorTracker = modules.aggregatorTracker;
   130→
   131→    this.events.on(NetworkEvent.peerConnected, this.onPeerConnected);
   132→    this.events.on(NetworkEvent.peerDisconnected, this.onPeerDisconnected);
   133→    this.chain.emitter.on(routes.events.EventType.head, this.onHead);
   134→    this.chain.emitter.on(routes.events.EventType.lightClientFinalityUpdate, ({data}) =>
   135→      this.onLightClientFinalityUpdate(data)
   136→    );
   137→    this.chain.emitter.on(routes.events.EventType.lightClientOptimisticUpdate, ({data}) =>
   138→      this.onLightClientOptimisticUpdate(data)
   139→    );
   140→    this.chain.emitter.on(ChainEvent.updateTargetCustodyGroupCount, this.onTargetGroupCountUpdated);
   141→    this.chain.emitter.on(ChainEvent.publishDataColumns, this.onPublishDataColumns);
   142→    this.chain.emitter.on(ChainEvent.publishBlobSidecars, this.onPublishBlobSidecars);
   143→    this.chain.emitter.on(ChainEvent.updateStatus, this.onUpdateStatus);
   144→  }
   145→
   146→  static async init({
   147→    opts,
   148→    config,
   149→    logger,
   150→    metrics,
   151→    chain,
   152→    db,
   153→    gossipHandlers,
   154→    privateKey,
   155→    peerStoreDir,
   156→    getReqRespHandler,
   157→  }: NetworkInitModules): Promise<Network> {
   158→    const events = new NetworkEventBus();
   159→    const aggregatorTracker = new AggregatorTracker();
   160→
   161→    const activeValidatorCount = chain.getHeadState().epochCtx.currentShuffling.activeIndices.length;
   162→    const initialStatus = chain.getStatus();
   163→    const initialCustodyGroupCount = chain.custodyConfig.targetCustodyGroupCount;
   164→
   165→    if (opts.useWorker) {
   166→      logger.info("running libp2p instance in worker thread");
   167→    }
   168→
   169→    const core = opts.useWorker
   170→      ? await WorkerNetworkCore.init({
   171→          opts: {
   172→            ...opts,
   173→            peerStoreDir,
   174→            metricsEnabled: Boolean(metrics),
   175→            activeValidatorCount,
   176→            genesisTime: chain.genesisTime,
   177→            initialStatus,
   178→            initialCustodyGroupCount,
   179→          },
   180→          config,
   181→          privateKey,
   182→          logger,
   183→          events,
   184→          metrics,
   185→          getReqRespHandler,
   186→        })
   187→      : await NetworkCore.init({
   188→          opts,
   189→          config,
   190→          privateKey,
   191→          peerStoreDir,
   192→          logger,
   193→          clock: chain.clock,
   194→          events,
   195→          getReqRespHandler,
   196→          metricsRegistry: metrics ? new RegistryMetricCreator() : null,
   197→          initialStatus,
   198→          initialCustodyGroupCount,
   199→          activeValidatorCount,
   200→        });
   201→
   202→    const networkProcessor = new NetworkProcessor(
   203→      {chain, db, config, logger, metrics, events, gossipHandlers, core, aggregatorTracker},
   204→      opts
   205→    );
   206→
   207→    const multiaddresses = opts.localMultiaddrs?.join(",");
   208→    const peerId = peerIdFromPrivateKey(privateKey);
   209→    logger.info(`PeerId ${peerIdToString(peerId)}, Multiaddrs ${multiaddresses}`);
   210→
   211→    return new Network({
   212→      opts,
   213→      privateKey,
   214→      config,
   215→      logger,
   216→      chain,
   217→      networkEventBus: events,
   218→      aggregatorTracker,
   219→      networkProcessor,
   220→      core,
   221→    });
   222→  }
   223→
   224→  get closed(): boolean {
   225→    return this.controller.signal.aborted;
   226→  }
   227→
   228→  /** Destroy this instance. Can only be called once. */
   229→  async close(): Promise<void> {
   230→    if (this.closed) return;
   231→
   232→    this.events.off(NetworkEvent.peerConnected, this.onPeerConnected);
   233→    this.events.off(NetworkEvent.peerDisconnected, this.onPeerDisconnected);
   234→    this.chain.emitter.off(routes.events.EventType.head, this.onHead);
   235→    this.chain.emitter.off(routes.events.EventType.lightClientFinalityUpdate, this.onLightClientFinalityUpdate);
   236→    this.chain.emitter.off(routes.events.EventType.lightClientOptimisticUpdate, this.onLightClientOptimisticUpdate);
   237→    this.chain.emitter.off(ChainEvent.updateTargetCustodyGroupCount, this.onTargetGroupCountUpdated);
   238→    this.chain.emitter.off(ChainEvent.publishDataColumns, this.onPublishDataColumns);
   239→    this.chain.emitter.off(ChainEvent.publishBlobSidecars, this.onPublishBlobSidecars);
   240→    this.chain.emitter.off(ChainEvent.updateStatus, this.onUpdateStatus);
   241→    await this.core.close();
   242→
   243→    // Used only for sleep() statements
   244→    this.controller.abort();
   245→    this.logger.debug("network core closed");
   246→  }
   247→
   248→  async scrapeMetrics(): Promise<string> {
   249→    return this.core.scrapeMetrics();
   250→  }
   251→
   252→  /**
   253→   * Request att subnets up `toSlot`. Network will ensure to mantain some peers for each
   254→   */
   255→  async prepareBeaconCommitteeSubnets(subscriptions: CommitteeSubscription[]): Promise<void> {
   256→    for (const subscription of subscriptions) {
   257→      if (subscription.isAggregator) {
   258→        this.aggregatorTracker.addAggregator(subscription.subnet, subscription.slot);
   259→      }
   260→    }
   261→    this.aggregatorTracker.prune();
   262→
   263→    return this.core.prepareBeaconCommitteeSubnets(subscriptions);
   264→  }
   265→
   266→  async prepareSyncCommitteeSubnets(subscriptions: CommitteeSubscription[]): Promise<void> {
   267→    return this.core.prepareSyncCommitteeSubnets(subscriptions);
   268→  }
   269→
   270→  /**
   271→   * The app layer needs to refresh the status of some peers. The sync have reached a target
   272→   */
