   279→  }
   280→
   281→  async reportPeer(peer: PeerIdStr, action: PeerAction, actionName: string): Promise<void> {
   282→    return this.core.reportPeer(peer, action, actionName);
   283→  }
   284→
   285→  // REST API queries
   286→  getConnectedPeers(): PeerIdStr[] {
   287→    return Array.from(this.connectedPeersSyncMeta.keys());
   288→  }
   289→
   290→  getConnectedPeerSyncMeta(peerId: PeerIdStr): PeerSyncMeta {
   291→    const syncMeta = this.connectedPeersSyncMeta.get(peerId);
   292→    if (!syncMeta) {
   293→      throw new Error(`peerId=${prettyPrintPeerIdStr(peerId)} not in connectedPeerSyncMeta`);
   294→    }
   295→    return {peerId, ...syncMeta};
   296→  }
   297→
   298→  getConnectedPeerCount(): number {
   299→    return this.connectedPeersSyncMeta.size;
   300→  }
   301→
   302→  async getNetworkIdentity(): Promise<routes.node.NetworkIdentity> {
   303→    return this.core.getNetworkIdentity();
   304→  }
   305→
   306→  /**
   307→   * Subscribe to all gossip events. Safe to call multiple times
   308→   */
   309→  async subscribeGossipCoreTopics(): Promise<void> {
   310→    if (!this.subscribedToCoreTopics) {
   311→      await this.core.subscribeGossipCoreTopics();
   312→      // Only mark subscribedToCoreTopics if worker resolved this call
   313→      this.subscribedToCoreTopics = true;
   314→    }
   315→  }
   316→
   317→  /**
   318→   * Unsubscribe from all gossip events. Safe to call multiple times
   319→   */
   320→  async unsubscribeGossipCoreTopics(): Promise<void> {
   321→    // Drop all the gossip validation queues
   322→    this.networkProcessor.dropAllJobs();
   323→
   324→    await this.core.unsubscribeGossipCoreTopics();
   325→    this.subscribedToCoreTopics = false;
   326→  }
   327→
   328→  isSubscribedToGossipCoreTopics(): boolean {
   329→    return this.subscribedToCoreTopics;
   330→  }
