   338→  async publishBeaconBlock(signedBlock: SignedBeaconBlock): Promise<number> {
   339→    const epoch = computeEpochAtSlot(signedBlock.message.slot);
   340→    const boundary = this.config.getForkBoundaryAtEpoch(epoch);
   341→
   342→    return this.publishGossip<GossipType.beacon_block>({type: GossipType.beacon_block, boundary}, signedBlock, {
   343→      ignoreDuplicatePublishError: true,
   344→    });
   345→  }
