   347→  async publishBlobSidecar(blobSidecar: deneb.BlobSidecar): Promise<number> {
   348→    const epoch = computeEpochAtSlot(blobSidecar.signedBlockHeader.message.slot);
   349→    const boundary = this.config.getForkBoundaryAtEpoch(epoch);
   350→
   351→    const subnet = blobSidecar.index;
   352→
   353→    return this.publishGossip<GossipType.blob_sidecar>({type: GossipType.blob_sidecar, boundary, subnet}, blobSidecar, {
   354→      ignoreDuplicatePublishError: true,
   355→    });
