   358→  async publishDataColumnSidecar(dataColumnSidecar: fulu.DataColumnSidecar): Promise<number> {
   359→    const epoch = computeEpochAtSlot(dataColumnSidecar.signedBlockHeader.message.slot);
   360→    const boundary = this.config.getForkBoundaryAtEpoch(epoch);
