   362→    const subnet = computeSubnetForDataColumnSidecar(this.config, dataColumnSidecar);
   363→    return this.publishGossip<GossipType.data_column_sidecar>(
   364→      {type: GossipType.data_column_sidecar, boundary, subnet},
   365→      dataColumnSidecar,
   366→      {
   367→        ignoreDuplicatePublishError: true,
   368→        // we ensure having all topic peers via prioritizePeers() function
   369→        // in the worse case, if there is 0 peer on the topic, the overall publish operation could be still a success
   370→        // because supernode will rebuild and publish missing data column sidecars for us
   371→        // hence we want to track sent peers as 0 instead of an error
   372→        allowPublishToZeroTopicPeers: true,
   373→      }
   374→    );
