   408→  async publishBlsToExecutionChange(blsToExecutionChange: capella.SignedBLSToExecutionChange): Promise<number> {
   409→    const publishChanges = [];
   410→    for (const boundary of getActiveForkBoundaries(this.config, this.clock.currentEpoch)) {
   411→      const fork = ForkSeq[boundary.fork];
   412→
   413→      if (fork >= ForkSeq.capella) {
   414→        const publishPromise = this.publishGossip<GossipType.bls_to_execution_change>(
   415→          {type: GossipType.bls_to_execution_change, boundary},
   416→          blsToExecutionChange,
   417→          {ignoreDuplicatePublishError: true}
   418→        );
   419→        publishChanges.push(publishPromise);
   420→      }
   421→    }
   422→
   423→    if (publishChanges.length === 0) {
   424→      throw Error("No capella+ fork active yet to publish blsToExecutionChange");
   425→    }
   426→    return Promise.any(publishChanges);
   427→  }
