   493→  private async publishGossip<K extends GossipType>(
   494→    topic: GossipTopicMap[K],
   495→    object: GossipTypeMap[K],
   496→    opts?: PublishOpts | undefined
   497→  ): Promise<number> {
   498→    const topicStr = stringifyGossipTopic(this.config, topic);
   499→    const sszType = getGossipSSZType(topic);
   500→    const messageData = (sszType.serialize as (object: GossipTypeMap[GossipType]) => Uint8Array)(object);
   501→    opts = {
   502→      ...opts,
   503→      ignoreDuplicatePublishError: gossipTopicIgnoreDuplicatePublishError[topic.type],
   504→    };
   505→    const sentPeers = await this.core.publishGossip(topicStr, messageData, opts);
   506→
   507→    this.logger.verbose("Publish to topic", {topic: topicStr, sentPeers, currentSlot: this.clock.currentSlot});
   508→    return sentPeers;
   509→  }
