   689→  private onLightClientFinalityUpdate = async (finalityUpdate: LightClientFinalityUpdate): Promise<void> => {
   690→    // TODO: Review is OK to remove if (this.hasAttachedSyncCommitteeMember())
   691→
   692→    try {
   693→      // messages SHOULD be broadcast after SYNC_MESSAGE_DUE_BPS of slot has transpired
   694→      // https://github.com/ethereum/consensus-specs/blob/dev/specs/altair/light-client/p2p-interface.md#sync-committee
   695→      await this.waitForSyncMessageCutoff(finalityUpdate.signatureSlot);
   696→      await this.publishLightClientFinalityUpdate(finalityUpdate);
   697→    } catch (e) {
   698→      // Non-mandatory route on most of network as of Oct 2022. May not have found any peers on topic yet
   699→      // Remove once https://github.com/ChainSafe/js-libp2p-gossipsub/issues/367
   700→      if (!isPublishToZeroPeersError(e as Error)) {
   701→        this.logger.debug("Error on BeaconGossipHandler.onLightclientFinalityUpdate", {}, e as Error);
   702→      }
   703→    }
