    97→    this.nodeId = opts.nodeId;
    98→    this.targetCustodyGroupCount = opts.initialCustodyGroupCount ?? this.config.CUSTODY_REQUIREMENT;
    99→    this.custodyColumns = getDataColumns(this.config, this.nodeId, this.targetCustodyGroupCount);
   100→    this.custodyColumnsIndex = this.getCustodyColumnsIndex(this.custodyColumns);
