   115→    this.sampledGroupCount = Math.max(this.targetCustodyGroupCount, this.config.SAMPLES_PER_SLOT);
   116→    this.sampleGroups = getCustodyGroups(this.config, this.nodeId, this.sampledGroupCount);
   117→    this.sampledColumns = getDataColumns(this.config, this.nodeId, this.sampledGroupCount);
