   123→  private getCustodyColumnsIndex(custodyColumns: ColumnIndex[]): Uint8Array {
   124→    // custody columns map which column maps to which index in the array of columns custodied
   125→    // with zero representing it is not custodied
   126→    const custodyColumnsIndex = new Uint8Array(NUMBER_OF_COLUMNS);
   127→    let custodyAtIndex = 1;
   128→    for (const columnIndex of custodyColumns) {
   129→      custodyColumnsIndex[columnIndex] = custodyAtIndex;
   130→      custodyAtIndex++;
   131→    }
   132→    return custodyColumnsIndex;
   133→  }
   134→}
