   136→function computeSubnetForDataColumn(config: ChainForkConfig, columnIndex: ColumnIndex): number {
   137→  return columnIndex % config.DATA_COLUMN_SIDECAR_SUBNET_COUNT;
   138→}
   139→
   140→/**
   141→ * Calculate the number of custody groups the node should subscribe to based on the node's effective balance
   142→ *
   143→ * SPEC FUNCTION
   144→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.3/specs/fulu/validator.md#validator-custody
   145→ */
   146→export function getValidatorsCustodyRequirement(config: ChainForkConfig, effectiveBalances: number[]): number {
   147→  if (effectiveBalances.length === 0) {
   148→    return config.CUSTODY_REQUIREMENT;
   149→  }
   150→
   151→  const totalNodeEffectiveBalance = effectiveBalances.reduce((total, effectiveBalance) => {
   152→    return total + effectiveBalance;
   153→  }, 0);
   154→
   155→  // Must custody one group for every BALANCE_PER_ADDITIONAL_CUSTODY_GROUP of effective balance
   156→  let validatorsCustodyRequirement = Math.floor(
   157→    totalNodeEffectiveBalance / config.BALANCE_PER_ADDITIONAL_CUSTODY_GROUP
   158→  );
   159→
   160→  // Any node with at least 1 validator must custody at least VALIDATOR_CUSTODY_REQUIREMENT
   161→  validatorsCustodyRequirement = Math.max(validatorsCustodyRequirement, config.VALIDATOR_CUSTODY_REQUIREMENT);
   162→
   163→  // Cannot custody more than NUMBER_OF_CUSTODY_GROUPS
   164→  validatorsCustodyRequirement = Math.min(validatorsCustodyRequirement, config.NUMBER_OF_CUSTODY_GROUPS);
   165→
   166→  return validatorsCustodyRequirement;
   167→}
   168→
   169→/**
   170→ * Converts a custody group to an array of column indices.  Should be 1-1 as long there are 128
   171→ * columns and 128 custody groups.
   172→ *
   173→ * SPEC FUNCTION
   174→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#compute_columns_for_custody_group
   175→ */
   176→export function computeColumnsForCustodyGroup(config: ChainForkConfig, custodyIndex: CustodyIndex): ColumnIndex[] {
   177→  if (custodyIndex >= config.NUMBER_OF_CUSTODY_GROUPS) {
   178→    throw Error(`Invalid custody index ${custodyIndex} >= ${config.NUMBER_OF_CUSTODY_GROUPS}`);
   179→  }
   180→  const columnsPerCustodyGroup = Number(NUMBER_OF_COLUMNS / config.NUMBER_OF_CUSTODY_GROUPS);
   181→  const columnIndexes = [];
   182→  for (let i = 0; i < columnsPerCustodyGroup; i++) {
   183→    columnIndexes.push(config.NUMBER_OF_CUSTODY_GROUPS * i + custodyIndex);
   184→  }
   185→  columnIndexes.sort((a, b) => a - b);
   186→  return columnIndexes;
   187→}
   188→
   189→/**
   190→ * Converts nodeId and a the number of custody groups to an array of custody indices. Indexes must be
   191→ * further converted to column indices
   192→ *
   193→ * SPEC FUNCTION
   194→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#get_custody_groups
   195→ */
   196→export function getCustodyGroups(config: ChainForkConfig, nodeId: NodeId, custodyGroupCount: number): CustodyIndex[] {
   197→  if (custodyGroupCount > config.NUMBER_OF_CUSTODY_GROUPS) {
   198→    throw Error(`Invalid custody group count ${custodyGroupCount} > ${config.NUMBER_OF_CUSTODY_GROUPS}`);
   199→  }
   200→
   201→  // Skip computation if all groups are custodied
   202→  if (custodyGroupCount === config.NUMBER_OF_CUSTODY_GROUPS) {
   203→    return Array.from({length: config.NUMBER_OF_CUSTODY_GROUPS}, (_, i) => i);
   204→  }
   205→
   206→  const custodyGroups: CustodyIndex[] = [];
   207→  // nodeId is in bigendian and all computes are in little endian
   208→  let currentId = bytesToBigInt(nodeId, "be");
   209→  while (custodyGroups.length < custodyGroupCount) {
   210→    // could be optimized
   211→    const currentIdBytes = ssz.UintBn256.serialize(currentId);
   212→    const custodyGroup = Number(
   213→      ssz.UintBn64.deserialize(digest(currentIdBytes).slice(0, 8)) % BigInt(config.NUMBER_OF_CUSTODY_GROUPS)
   214→    );
   215→
   216→    if (!custodyGroups.includes(custodyGroup)) {
   217→      custodyGroups.push(custodyGroup);
   218→    }
   219→
   220→    const willOverflow = currentIdBytes.reduce((acc, elem) => acc && elem === 0xff, true);
   221→    if (willOverflow) {
   222→      currentId = BigInt(0);
   223→    } else {
   224→      currentId++;
   225→    }
   226→  }
   227→
   228→  custodyGroups.sort((a, b) => a - b);
   229→  return custodyGroups;
   230→}
