   246→/**
   247→ * Computes the cells for each blob and combines them with cell proofs.
   248→ * Similar to the computeMatrix function described below.
   249→ *
   250→ * SPEC FUNCTION (note: spec currently computes proofs, but we already have them)
   251→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#compute_matrix
   252→ */
   253→export async function getCellsAndProofs(
   254→  blobBundles: fulu.BlobAndProofV2[]
   255→): Promise<{cells: Uint8Array[]; proofs: Uint8Array[]}[]> {
   256→  const blobsAndProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[] = [];
   257→  for (const {blob, proofs} of blobBundles) {
   258→    const cells = await kzg.asyncComputeCells(blob);
   259→    blobsAndProofs.push({cells, proofs});
   260→  }
   261→  return blobsAndProofs;
   262→}
   263→
   264→/**
   265→ * Given a signed block header and the commitments, inclusion proof, cells/proofs associated with
   266→ * each blob in the block, assemble the sidecars which can be distributed to peers.
   267→ *
   268→ * SPEC FUNCTION
   269→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/validator.md#get_data_column_sidecars
   270→ */
   271→export function getDataColumnSidecars(
   272→  signedBlockHeader: SignedBeaconBlockHeader,
   273→  kzgCommitments: deneb.KZGCommitment[],
   274→  kzgCommitmentsInclusionProof: fulu.KzgCommitmentsInclusionProof,
   275→  cellsAndKzgProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[]
   276→): fulu.DataColumnSidecars {
   277→  if (cellsAndKzgProofs.length !== kzgCommitments.length) {
   278→    throw Error("Invalid cellsAndKzgProofs length for getDataColumnSidecars");
   279→  }
   280→
   281→  const sidecars: fulu.DataColumnSidecars = [];
   282→  for (let columnIndex = 0; columnIndex < NUMBER_OF_COLUMNS; columnIndex++) {
   283→    const columnCells = [];
   284→    const columnProofs = [];
   285→    for (const {cells, proofs} of cellsAndKzgProofs) {
   286→      columnCells.push(cells[columnIndex]);
   287→      columnProofs.push(proofs[columnIndex]);
   288→    }
   289→    sidecars.push({
   290→      index: columnIndex,
   291→      column: columnCells,
   292→      kzgCommitments,
   293→      kzgProofs: columnProofs,
   294→      signedBlockHeader,
   295→      kzgCommitmentsInclusionProof,
   296→    });
   297→  }
   298→  return sidecars;
   299→}
   300→
   301→/**
   302→ * Given a signed block and the cells/proofs associated with each blob in the
   303→ * block, assemble the sidecars which can be distributed to peers.
   304→ *
   305→ * SPEC FUNCTION
   306→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/validator.md#get_data_column_sidecars_from_block
   307→ */
   308→export function getDataColumnSidecarsFromBlock(
   309→  config: ChainForkConfig,
   310→  signedBlock: SignedBeaconBlock<ForkPostFulu>,
   311→  cellsAndKzgProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[]
   312→): fulu.DataColumnSidecars {
   313→  // TODO GLOAS: Need to get blobKzgCommitments from somewhere else
   314→  const blobKzgCommitments = (signedBlock.message.body as BeaconBlockBody<ForkPostFulu & ForkPreGloas>)
   315→    .blobKzgCommitments;
   316→
   317→  // No need to create data column sidecars if there are no blobs
   318→  if (blobKzgCommitments.length === 0) {
   319→    return [];
   320→  }
   321→
   322→  const fork = config.getForkName(signedBlock.message.slot);
   323→  const signedBlockHeader = signedBlockToSignedHeader(config, signedBlock);
   324→
   325→  const kzgCommitmentsInclusionProof = computePostFuluKzgCommitmentsInclusionProof(fork, signedBlock.message.body);
   326→
   327→  return getDataColumnSidecars(signedBlockHeader, blobKzgCommitments, kzgCommitmentsInclusionProof, cellsAndKzgProofs);
   328→}
   329→
   330→/**
   331→ * Given a DataColumnSidecar and the cells/proofs associated with each blob corresponding
   332→ * to the commitments it contains, assemble all sidecars for distribution to peers.
   333→ *
   334→ * SPEC FUNCTION
   335→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/validator.md#get_data_column_sidecars_from_column_sidecar
   336→ */
   337→export function getDataColumnSidecarsFromColumnSidecar(
   338→  sidecar: fulu.DataColumnSidecar,
   339→  cellsAndKzgProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[]
   340→): fulu.DataColumnSidecars {
   341→  return getDataColumnSidecars(
   342→    sidecar.signedBlockHeader,
   343→    sidecar.kzgCommitments,
   344→    sidecar.kzgCommitmentsInclusionProof,
   345→    cellsAndKzgProofs
   346→  );
   347→}
