   349→/**
   350→ * If we receive more than half of NUMBER_OF_COLUMNS (64) we should recover all remaining columns
   351→ */
   352→export async function recoverDataColumnSidecars(
   353→  blockInput: BlockInputColumns,
   354→  emitter: ChainEventEmitter,
   355→  metrics: Metrics | null
   356→): Promise<DataColumnReconstructionCode> {
   357→  const existingColumns = blockInput.getAllColumns();
   358→  const columnCount = existingColumns.length;
   359→  if (columnCount >= NUMBER_OF_COLUMNS) {
   360→    // We have all columns
   361→    return DataColumnReconstructionCode.NotAttemptedAlreadyFull;
